import React, { useState, useEffect } from "react";
import { Link, useLocation } from "react-router-dom";

function Layout({ children }) {
  const location = useLocation();
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [treeviewOpen, setTreeviewOpen] = useState({ departments: false });

  useEffect(() => {
    if (location.pathname.startsWith("/departments")) {
      setTreeviewOpen({ ...treeviewOpen, departments: true });
    } else {
      setTreeviewOpen({ ...treeviewOpen, departments: false });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [location.pathname]);

  const toggleSidebar = () => setSidebarCollapsed(!sidebarCollapsed);
  const toggleTreeview = (menu) => {
    setTreeviewOpen({ ...treeviewOpen, [menu]: !treeviewOpen[menu] });
  };

  return (
    <div
      className={`hold-transition sidebar-mini layout-fixed wrapper ${
        sidebarCollapsed ? "sidebar-collapse" : ""
      }`}
      style={{ minHeight: "100vh" }}
    >
      {/* Navbar */}
      <nav className="main-header navbar navbar-expand navbar-white navbar-light">
        <ul className="navbar-nav">
          <li className="nav-item">
            <button
              className="nav-link btn btn-light"
              style={{ border: "none", background: "transparent" }}
              onClick={toggleSidebar}
            >
              <i className="fas fa-bars"></i>
            </button>
          </li>
          <li className="nav-item d-none d-sm-inline-block">
            <Link to="/" className="nav-link">
              Home
            </Link>
          </li>
        </ul>
      </nav>

      {/* Sidebar */}
      <aside className="main-sidebar sidebar-dark-primary elevation-4">
        <Link to="/" className="brand-link">
          <span className="brand-text font-weight-light">ORA Admin</span>
        </Link>

        <div className="sidebar">
          <nav className="mt-2">
            <ul
              className="nav nav-pills nav-sidebar flex-column"
              data-widget="treeview"
              role="menu"
              data-accordion="false"
            >
              <li className="nav-item">
                <Link
                  to="/"
                  className={`nav-link ${location.pathname === "/" ? "active" : ""}`}
                >
                  <i className="nav-icon fas fa-tachometer-alt"></i>
                  <p>Dashboard</p>
                </Link>
              </li>

              <li className="nav-item">
                <Link
                  to="/users"
                  className={`nav-link ${location.pathname === "/users" ? "active" : ""}`}
                >
                  <i className="nav-icon fas fa-users"></i>
                  <p>Users</p>
                </Link>
              </li>

              <li className={`nav-item ${treeviewOpen.departments ? "menu-open" : ""}`}>
                <a
                  href="#!"
                  className={`nav-link ${
                    location.pathname.startsWith("/departments") ? "active" : ""
                  }`}
                  onClick={() => toggleTreeview("departments")}
                >
                  <i className="nav-icon fas fa-building"></i>
                  <p>
                    Departments
                    <i className="right fas fa-angle-left"></i>
                  </p>
                </a>
                <ul
                  className="nav nav-treeview"
                  style={{ display: treeviewOpen.departments ? "block" : "none" }}
                >
                  <li className="nav-item">
                    <Link
                      to="/departments/hr"
                      className={`nav-link ${location.pathname === "/departments/hr" ? "active" : ""}`}
                    >
                      <i className="far fa-circle nav-icon"></i>
                      <p>HR</p>
                    </Link>
                  </li>
                  <li className="nav-item">
                    <Link
                      to="/departments/it"
                      className={`nav-link ${location.pathname === "/departments/it" ? "active" : ""}`}
                    >
                      <i className="far fa-circle nav-icon"></i>
                      <p>IT</p>
                    </Link>
                  </li>
                </ul>
              </li>
            </ul>
          </nav>
        </div>
      </aside>

      {/* Content Wrapper */}
      <div className="content-wrapper">
        <section className="content-header">
          <div className="container-fluid">{children}</div>
        </section>
      </div>
    </div>
  );
}

export default Layout;
